// Foundry VTT Macro: Clear Compendium (V2 Application)
(async () => {
    const packKeyRaw = await foundry.applications.api.DialogV2.prompt({
        window: { title: "Очистка компендиума" },
        content: `
            <p>Введите системный ключ (например, <b>dedrel.talents</b>):</p>
            <div class="form-group" style="margin-bottom: 10px;">
                <input type="text" name="packKey" value="dedrel." style="width: 100%;"/>
            </div>
            <p style="color: red; font-weight: bold; margin-bottom: 10px;">ВНИМАНИЕ: Это действие удалит всё безвозвратно!</p>
        `,
        ok: {
            label: "Очистить",
            icon: "fas fa-trash",
            callback: (event, button, dialog) => button.form.elements.packKey.value
        },
        rejectClose: false
    });

    if (!packKeyRaw) return;

    const packKey = packKeyRaw.trim();
    if (!packKey) return ui.notifications.error("Ключ пустой.");

    const pack = game.packs.get(packKey);
    if (!pack) return ui.notifications.error(`Компендиум ${packKey} не найден.`);

    const confirmDelete = await foundry.applications.api.DialogV2.confirm({
        window: { title: "Точно удалить?" },
        content: `<p>Безвозвратно удалить <b>ВСЕ</b> данные из ${pack.title}?</p>`,
        rejectClose: false
    });

    if (!confirmDelete) return;

    const wasLocked = pack.locked;
    if (wasLocked) await pack.configure({locked: false});

    try {
        const docs = await pack.getDocuments();
        const documentIds = docs.map(d => d.id);

        if (documentIds.length > 0) {
            ui.notifications.info(`Удаляем ${documentIds.length} предметов из ${packKey}...`);
            await pack.documentClass.deleteDocuments(documentIds, {pack: packKey});
        }

        if (pack.folders && pack.folders.size > 0) {
            const folders = Array.from(pack.folders);
            ui.notifications.info(`Удаляем папки...`);
            for (let f of folders) {
                try {
                    await f.delete();
                } catch(err) {}
            }
        }

        ui.notifications.info(`Компендиум ${packKey} полностью очищен!`);
    } catch (e) {
        console.error(e);
        ui.notifications.error("Ошибка при очистке: " + e.message);
    } finally {
        if (wasLocked) await pack.configure({locked: true});
    }
})();
